import math
import numpy as np

rng = np.random.default_rng(27)
I2 = np.eye(2); X = np.array([[0, 1], [1, 0]]); Z = np.array([[1, 0], [0, -1]])
def op_on(n, gate, q):
    ops = [I2] * n; ops[q] = gate
    M = ops[0]
    for o in ops[1:]: M = np.kron(M, o)
    return M
def ising_hamiltonian(n, g=1.0):
    H = np.zeros((2 ** n, 2 ** n))
    for i in range(n - 1): H -= op_on(n, Z, i) @ op_on(n, Z, i + 1)
    for i in range(n): H -= g * op_on(n, X, i)
    return H

# --- a hardware-efficient ansatz: layers of RY rotations and a ladder of CNOTs, simulated with the exact state vector
def ry(theta):
    c, s = math.cos(theta / 2), math.sin(theta / 2)
    return np.array([[c, -s], [s, c]])
def apply_1q(state, gate, q, n):
    psi = np.moveaxis(state.reshape((2,) * n), q, 0)
    psi = np.tensordot(gate, psi, axes=([1], [0]))
    return np.moveaxis(psi, 0, q).reshape(-1)
def apply_cnot(state, c, t, n):
    psi = state.reshape((2,) * n).copy()
    idx = [slice(None)] * n
    idx[c] = 1
    sub = psi[tuple(idx)]                                                    # the block where the control is 1
    t_axis = t if t < c else t - 1
    psi[tuple(idx)] = np.flip(sub, axis=t_axis)                              # flip the target within that block
    return psi.reshape(-1)
def ansatz_state(n, params, layers):
    psi = np.zeros(2 ** n); psi[0] = 1
    p = params.reshape(layers, n)
    for l in range(layers):
        for q in range(n):
            psi = apply_1q(psi, ry(p[l, q]), q, n)
        for i in range(n - 1):
            psi = apply_cnot(psi, i, i + 1, n)
    return psi
def energy(H, n, params, layers):
    psi = ansatz_state(n, params, layers)
    return float(psi @ H @ psi)

n, layers = 4, 3
H = ising_hamiltonian(n)
ground = float(np.linalg.eigvalsh(H)[0])
# --- the parameter-shift rule gives exact gradients from two extra circuit evaluations per parameter; verified against finite differences
params = rng.uniform(0, 2 * np.pi, n * layers)
def gradient_shift(params):
    g = np.zeros_like(params)
    for k in range(len(params)):
        plus, minus = params.copy(), params.copy()
        plus[k] += np.pi / 2; minus[k] -= np.pi / 2
        g[k] = 0.5 * (energy(H, n, plus, layers) - energy(H, n, minus, layers))
    return g
def gradient_fd(params, h=1e-6):
    return np.array([(energy(H, n, params + h * np.eye(len(params))[k], layers) - energy(H, n, params - h * np.eye(len(params))[k], layers)) / (2 * h) for k in range(len(params))])
print("parameter-shift gradient equals the finite-difference gradient (max difference):", f"{np.abs(gradient_shift(params) - gradient_fd(params)).max():.1e}")

# --- VQE: gradient descent with the parameter-shift gradient
print()
print(f"exact ground-state energy of the 4-spin transverse-field Ising chain: {ground:.6f}")
print(f"{'restart':>8} {'initial energy':>15} {'energy after 200 iterations':>28} {'error vs exact':>16}")
finals = []
for restart in range(6):
    theta = rng.uniform(0, 2 * np.pi, n * layers)
    e0 = energy(H, n, theta, layers)
    for it in range(200):
        theta = theta - 0.1 * gradient_shift(theta)
    e = energy(H, n, theta, layers)
    finals.append(e)
    print(f"{restart:>8} {e0:>15.4f} {e:>28.6f} {e - ground:>16.6f}")
print(f"best of 6 restarts: error {min(finals) - ground:.6f}; worst: error {max(finals) - ground:.6f}")
print("the variational principle guarantees energy >= ground state energy for every parameter value; gradient descent can stall in a local minimum, so different random starts end at different energies and the best start is kept")
print("shots needed: the energy is a sum of Pauli terms, each estimated with ~ 1/epsilon^2 samples; here", 2 * n - 1, "terms")

# --- barren plateaus: the variance of a gradient over random parameters shrinks exponentially with the number of qubits for deep random ansaetze
print()
print(f"{'qubits':>7} {'layers':>7} {'variance of dE/dtheta_0 over 150 random initialisations':>58}")
for nq, ly in ((2, 8), (4, 16), (6, 24), (8, 32), (10, 40)):
    Hq = np.zeros((2 ** nq, 2 ** nq)); Hq += op_on(nq, Z, 0) @ op_on(nq, Z, 1)                # a local cost function: Z0 Z1
    def en(params):
        psi = ansatz_state(nq, params, ly)
        return float(psi @ Hq @ psi)
    grads = []
    for _ in range(150):
        pr = rng.uniform(0, 2 * np.pi, nq * ly)
        plus, minus = pr.copy(), pr.copy(); plus[0] += np.pi / 2; minus[0] -= np.pi / 2
        grads.append(0.5 * (en(plus) - en(minus)))
    print(f"{nq:>7} {ly:>7} {np.var(grads):>58.5f}")
print("the variance falls with the number of qubits when the circuit is deep enough to look random (McClean et al.); gradients vanish and training stalls, which is a design constraint on ansaetze, not a flaw of the algorithm")

import math
import numpy as np

# --- a quantum kernel from a data-encoding circuit, simulated exactly. The "quantum" part is only the kernel k(x, y) = |<phi(x)|phi(y)>|^2.
rng = np.random.default_rng(210)
def ry_gate(a):
    c, s = math.cos(a / 2), math.sin(a / 2); return np.array([[c, -s], [s, c]])
def feature_state(x, n=3, reps=2):
    """angle-encode the data point x (2 features) into n qubits with entangling ZZ phases"""
    psi = np.zeros(2 ** n, dtype=complex); psi[0] = 1
    H = np.array([[1, 1], [1, -1]]) / math.sqrt(2)
    def one(gate, q, s):
        t = np.moveaxis(s.reshape((2,) * n), q, 0)
        t = np.tensordot(gate, t, axes=([1], [0]))
        return np.moveaxis(t, 0, q).reshape(-1)
    for _ in range(reps):
        for q in range(n):
            psi = one(H, q, psi)
            psi = one(np.diag([np.exp(-1j * x[q % 2] / 2), np.exp(1j * x[q % 2] / 2)]), q, psi)       # Z-rotation by the feature
        for a in range(n):
            for b in range(a + 1, n):
                phase = np.array([np.exp(-1j * (x[0] * x[1]) * (1 if ((i >> (n - 1 - a)) & 1) == ((i >> (n - 1 - b)) & 1) else -1) / 2) for i in range(2 ** n)])
                psi = psi * phase                                           # ZZ-type entangling phase depending on both features
    return psi
def quantum_kernel(A, B):
    SA = np.array([feature_state(a) for a in A]); SB = np.array([feature_state(b) for b in B])
    return np.abs(SA.conj() @ SB.T) ** 2
def rbf_kernel(A, B, gamma=2.0):
    d = ((A[:, None, :] - B[None, :, :]) ** 2).sum(-1)
    return np.exp(-gamma * d)

# a toy data set: two concentric rings (a classically learnable problem)
def make_data(m):
    angles = rng.uniform(0, 2 * np.pi, m); radius = np.where(rng.random(m) < 0.5, 0.6, 1.4) + rng.normal(0, 0.12, m)
    return np.c_[radius * np.cos(angles), radius * np.sin(angles)], (radius > 1.0).astype(int)
Xtr, ytr = make_data(60); Xte, yte = make_data(200)

def fit_predict(kernel, lam=1e-2):
    K = kernel(Xtr, Xtr)
    alpha = np.linalg.solve(K + lam * np.eye(len(Xtr)), 2 * ytr - 1)         # kernel ridge regression on +/- 1 labels
    return (kernel(Xte, Xtr) @ alpha > 0).astype(int)
print(f"{'kernel':<28} {'test accuracy (200 points)':>28}")
for name, kernel in (("quantum (3 qubits, 2 reps)", quantum_kernel), ("classical RBF (gamma 2)", rbf_kernel), ("classical linear", lambda A, B: A @ B.T + 1)):
    print(f"{name:<28} {float((fit_predict(kernel) == yte).mean()):>28.3f}")
print("on this toy problem a plain classical kernel does as well or better; a quantum kernel is only interesting if no classical kernel can match it, and that has to be shown, not assumed")

# --- kernels are Gram matrices: positive semidefinite with unit diagonal; and the concentration problem for many qubits
K = quantum_kernel(Xtr[:20], Xtr[:20])
print()
print("quantum kernel matrix: symmetric, unit diagonal, positive semidefinite:", np.allclose(K, K.T), np.allclose(np.diag(K), 1), bool(np.linalg.eigvalsh(K).min() > -1e-9))
def feature_state_random(n, rng):
    # a Haar-random state stands in for the output of a deep expressive encoding circuit
    v = rng.normal(size=2 ** n) + 1j * rng.normal(size=2 ** n); return v / np.linalg.norm(v)
print(f"{'qubits':>7} {'mean kernel value between two random feature states':>54} {'std of the kernel value':>25}")
for n in (2, 4, 8, 12, 16):
    vals = [abs(np.vdot(feature_state_random(n, rng), feature_state_random(n, rng))) ** 2 for _ in range(300)]
    print(f"{n:>7} {np.mean(vals):>54.6f} {np.std(vals):>25.6f}")
print("for expressive encodings the kernel values concentrate around 2^-n: all points look equally dissimilar, the Gram matrix approaches the identity and nothing can be learned unless exponentially many shots resolve the tiny differences")
print("dequantization results show that for some quantum machine learning proposals with classical data and low-rank assumptions, classical algorithms of comparable speed exist (Tang); an advantage claim needs an end-to-end comparison including data loading")
